import{_ as t,o as l,c as e,ae as n}from"./chunks/framework.DJK_dC0-.js";const u=JSON.parse('{"title":"Pi Agent Runtime 定制化","description":"","frontmatter":{},"headers":[],"relativePath":"tutorial/pi-agent-runtime.md","filePath":"tutorial/pi-agent-runtime.md"}'),i={name:"tutorial/pi-agent-runtime.md"};function o(s,a,p,d,r,c){return l(),e("div",null,[...a[0]||(a[0]=[n(`<h1 id="pi-agent-runtime-定制化" tabindex="-1">Pi Agent Runtime 定制化 <a class="header-anchor" href="#pi-agent-runtime-定制化" aria-label="Permalink to &quot;Pi Agent Runtime 定制化&quot;">​</a></h1><p>本页定义把知识库 Agent 推进为可复用 Agent Runtime 的练习合同，让 Context、Skill、Tool、Hook/Policy 和 Eval 成为可版本化、可测试、可回滚的系统资产。下方只有策略函数示例；完整 Loop、checkpoint、Skill 加载和真实 Pi 集成尚待学习者实现，案例保持 <code>not-run</code>。</p><h2 id="运行链" tabindex="-1">运行链 <a class="header-anchor" href="#运行链" aria-label="Permalink to &quot;运行链&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>用户目标</span></span>
<span class="line"><span>→ Context 选择与裁剪</span></span>
<span class="line"><span>→ Skill 路由</span></span>
<span class="line"><span>→ Tool schema 与权限检查</span></span>
<span class="line"><span>→ 执行前 Hook/Policy 与必要人工批准</span></span>
<span class="line"><span>→ Agent Loop 中的工具执行（每次调用重新检查）</span></span>
<span class="line"><span>→ 执行后结果验证与审计</span></span>
<span class="line"><span>→ 结果、引用、trace</span></span>
<span class="line"><span>→ Eval 与版本比较</span></span>
<span class="line"><span>→ 资产沉淀或回滚</span></span></code></pre></div><h2 id="五层合同" tabindex="-1">五层合同 <a class="header-anchor" href="#五层合同" aria-label="Permalink to &quot;五层合同&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层</th><th>负责什么</th><th>最小验收</th></tr></thead><tbody><tr><td>Context</td><td>系统规则、项目规则、任务、画像、来源和上下文预算</td><td>替换一条约束后能解释保留和丢弃</td></tr><tr><td>Skill</td><td>触发条件、步骤、工具允许列表、输出和失败处理</td><td>新增 Skill 不改核心 Loop</td></tr><tr><td>Tool</td><td>输入/输出 schema、权限、超时、重试、幂等、审计</td><td>非法参数和越权调用失败</td></tr><tr><td>Hook/Policy</td><td>隐私、权限、来源、成本、完成证据和人工确认</td><td>高影响动作未批准时停止</td></tr><tr><td>Eval</td><td>Golden、BadCase、轨迹、指标、版本对比和回滚</td><td>改动后报告退化样本</td></tr></tbody></table><h2 id="python-教学实现" tabindex="-1">Python 教学实现 <a class="header-anchor" href="#python-教学实现" aria-label="Permalink to &quot;Python 教学实现&quot;">​</a></h2><p>先用标准库实现可确定复现的 Runtime：</p><div class="py-demo"><div class="py-demo-header"><span>Python</span><button class="py-demo-run" type="button">Run</button></div><pre class="language-python"><code>from dataclasses import dataclass
from typing import Callable

@dataclass(frozen=True)
class ToolSpec:
    name: str
    handler: Callable
    read_only: bool
    requires_approval: bool

def can_run(tool: ToolSpec, approved: bool) -&gt; bool:
    return approved or (tool.read_only and not tool.requires_approval)
</code></pre><div class="py-demo-output">Click Run to see output</div></div><p><code>ToolSpec</code> 来自可信工具注册表，<code>approved</code> 来自绑定本次工具、参数和身份的审批记录，不能使用模型自行声明的字段。写工具默认需要批准；显式要求审批的只读工具也必须等待批准。此函数只回答审批是否满足，调用前仍须独立通过身份、范围与参数检查；批准不覆盖其他拒绝条件。</p><p>然后把它迁移到真实模型、MCP、FastAPI 或 Pi 运行时。迁移时保持工具 schema、trace id、错误分类和评测集不变。</p><h2 id="练习顺序" tabindex="-1">练习顺序 <a class="header-anchor" href="#练习顺序" aria-label="Permalink to &quot;练习顺序&quot;">​</a></h2><ol><li>注册一个只读知识检索工具；</li><li>注册一个评测运行器；</li><li>为工具增加 schema 和结构化错误；</li><li>加入隐私扫描和来源检查 Hook；</li><li>注入工具结果错配、超时和重复调用；</li><li>用 Golden/BadCase 比较两个 Skill 版本；</li><li>让运行中断后从 checkpoint 恢复；</li><li>将知识库 Skill 迁移为 Workflow 任务执行 Skill。</li></ol><h2 id="真实业务迁移" tabindex="-1">真实业务迁移 <a class="header-anchor" href="#真实业务迁移" aria-label="Permalink to &quot;真实业务迁移&quot;">​</a></h2><p>可以把测试知识库迁移为以下脱敏工作流：</p><ul><li>输入测试需求或回归问题；</li><li>读取测试规则、接口说明和历史异常；</li><li>选择检索、分析、报告或只读查询工具；</li><li>生成带来源的建议；</li><li>高影响动作保留人工确认；</li><li>保存执行 trace、失败分类和报告链接。</li></ul><p>生产数据、用户凭据和真实业务副作用不进入课程 fixture。要证明系统具备岗位能力，必须同时展示工具合同、权限边界、故障注入、Eval 报告和回滚路径。</p><h2 id="面试验收" tabindex="-1">面试验收 <a class="header-anchor" href="#面试验收" aria-label="Permalink to &quot;面试验收&quot;">​</a></h2><p>候选人应能说明：</p><ul><li>为什么 Context、Skill、Tool、Hook 要分层；</li><li>如何新增 Skill 而不修改核心运行时；</li><li>如何保证不同语言工具的错误、超时和 trace 语义一致；</li><li>如何防止模型伪造工具结果或完成状态；</li><li>如何把一次真实排障沉淀为 Golden/BadCase；</li><li>如何在上下文不足时安全停止。</li></ul><h2 id="迁移题" tabindex="-1">迁移题 <a class="header-anchor" href="#迁移题" aria-label="Permalink to &quot;迁移题&quot;">​</a></h2><p>把知识库 Skill 迁移成 Workflow 任务 Skill：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>需求 → 规格 → 资源绑定 → 执行 → 证据 → 独立核验 → 人工验收</span></span></code></pre></div><p>要求保持：</p><ul><li>输入和输出合同；</li><li>trace 和幂等键；</li><li>权限和人工确认；</li><li>失败分类和恢复；</li><li>Eval 与回滚证据。</li></ul><p>这一步把 Python Agent 能力连接到 Workflow、Career 和后续 Java/Go 实现。</p>`,26)])])}const m=t(i,[["render",o]]);export{u as __pageData,m as default};
